# Pulumi ComponentResource: Application Infrastructure Stack

Here's a complete Pulumi TypeScript ComponentResource that wraps S3, RDS, and IAM resources with dev/prod environment support.

## Core Component (`index.ts`)

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ApplicationStackArgs {
  projectName: string;
  environment: string;
  bucketVersioning?: boolean;
  bucketEncryption?: string;
  dbInstanceClass?: string;
  dbAllocatedStorage?: number;
  dbMultiAz?: boolean;
  dbDeletionProtection?: boolean;
  dbBackupRetentionPeriods?: number;
  kmsKeyId?: string;
}

export class ApplicationStack extends pulumi.ComponentResource {
  public bucket: aws.s3.Bucket;
  public rdsInstance: aws.rds.Instance;
  public iamRole: aws.iam.Role;
  public iamInstanceProfile: aws.iam.InstanceProfile;

  public bucketArn: pulumi.Output<string>;
  public bucketName: pulumi.Output<string>;
  public rdsEndpoint: pulumi.Output<string>;
  public rdsArn: pulumi.Output<string>;
  public iamRoleArn: pulumi.Output<string>;

  constructor(
    name: string,
    args: ApplicationStackArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:infrastructure:ApplicationStack", name, {}, opts);

    const config = new pulumi.Config();
    const resourcePrefix = `${args.projectName}-${args.environment}`;

    // ========================================
    // S3 Bucket with versioning & encryption
    // ========================================
    this.bucket = new aws.s3.Bucket(
      `${resourcePrefix}-bucket`,
      {
        bucketPrefix: resourcePrefix,
        versioning: {
          enabled: args.bucketVersioning ?? true,
        },
        serverSideEncryptionConfiguration: {
          rule: {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: args.bucketEncryption ?? "AES256",
              kmsMasterKeyId:
                args.bucketEncryption === "aws:kms" ? args.kmsKeyId : undefined,
            },
          },
        },
        tags: {
          Environment: args.environment,
          ManagedBy: "Pulumi",
        },
      },
      { parent: this }
    );

    // Block all public access
    new aws.s3.BucketPublicAccessBlock(
      `${resourcePrefix}-bucket-pab`,
      {
        bucket: this.bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      { parent: this }
    );

    // ========================================
    // RDS PostgreSQL Instance
    // ========================================
    const dbPassword = config.requireSecret("dbPassword");

    this.rdsInstance = new aws.rds.Instance(
      `${resourcePrefix}-postgres`,
      {
        allocatedStorage: args.dbAllocatedStorage ?? 20,
        storageType: "gp2",
        engine: "postgres",
        engineVersion: "15.3",
        instanceClass: args.dbInstanceClass ?? "db.t3.micro",
        dbName: "appdb",
        username: "postgres",
        password: dbPassword,
        parameterGroupName: new aws.rds.ParameterGroup(
          `${resourcePrefix}-pg`,
          {
            family: "postgres15",
            parameters: [
              {
                name: "log_connections",
                value: "1",
              },
            ],
          },
          { parent: this }
        ).name,
        multiAz: args.dbMultiAz ?? false,
        deletionProtection: args.dbDeletionProtection ?? true,
        skipFinalSnapshot: false,
        finalSnapshotIdentifierPrefix: resourcePrefix,
        backupRetentionPeriod: args.dbBackupRetentionPeriods ?? 7,
        storageEncrypted: true,
        publiclyAccessible: false,
        tags: {
          Environment: args.environment,
          ManagedBy: "Pulumi",
        },
      },
      { parent: this }
    );

    // ========================================
    // IAM Role for Service Accounts
    // ========================================
    this.iamRole = new aws.iam.Role(
      `${resourcePrefix}-service-role`,
      {
        assumeRolePolicy: pulumi.output({
          Version: "2012-10-17",
          Statement: [
            {
              Action: "sts:AssumeRole",
              Effect: "Allow",
              Principal: {
                Service: ["ec2.amazonaws.com", "ecs-tasks.amazonaws.com"],
              },
            },
          ],
        }).apply(JSON.stringify),
        tags: {
          Environment: args.environment,
          ManagedBy: "Pulumi",
        },
      },
      { parent: this }
    );

    // Instance profile for EC2
    this.iamInstanceProfile = new aws.iam.InstanceProfile(
      `${resourcePrefix}-instance-profile`,
      {
        role: this.iamRole.name,
      },
      { parent: this }
    );

    // S3 policy: least privilege (scoped to specific bucket)
    new aws.iam.RolePolicy(
      `${resourcePrefix}-s3-policy`,
      {
        role: this.iamRole.id,
        policy: this.bucket.arn.apply((arn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Sid: "S3ObjectAccess",
                Effect: "Allow",
                Action: ["s3:GetObject", "s3:PutObject"],
                Resource: `${arn}/*`,
              },
              {
                Sid: "S3ListBucket",
                Effect: "Allow",
                Action: ["s3:ListBucket"],
                Resource: arn,
              },
            ],
          })
        ),
      },
      { parent: this }
    );

    // RDS policy: connection only (no wildcard actions)
    new aws.iam.RolePolicy(
      `${resourcePrefix}-rds-policy`,
      {
        role: this.iamRole.id,
        policy: this.rdsInstance.arn.apply((arn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Sid: "RDSConnect",
                Effect: "Allow",
                Action: ["rds-db:connect"],
                Resource: arn,
              },
            ],
          })
        ),
      },
      { parent: this }
    );

    // Secrets Manager policy: read DB secret only
    const secretArn = pulumi.interpolate`arn:aws:secretsmanager:${aws.getRegionOutput().name}:${aws.getCallerIdentityOutput().accountId}:secret:${resourcePrefix}/db/*`;
    new aws.iam.RolePolicy(
      `${resourcePrefix}-secrets-policy`,
      {
        role: this.iamRole.id,
        policy: secretArn.apply((arn) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Sid: "SecretsRead",
                Effect: "Allow",
                Action: ["secretsmanager:GetSecretValue"],
                Resource: arn,
              },
            ],
          })
        ),
      },
      { parent: this }
    );

    // Export outputs
    this.bucketArn = this.bucket.arn;
    this.bucketName = this.bucket.id;
    this.rdsEndpoint = this.rdsInstance.endpoint;
    this.rdsArn = this.rdsInstance.arn;
    this.iamRoleArn = this.iamRole.arn;

    this.registerOutputs({
      bucketArn: this.bucketArn,
      bucketName: this.bucketName,
      rdsEndpoint: this.rdsEndpoint,
      rdsArn: this.rdsArn,
      iamRoleArn: this.iamRoleArn,
    });
  }
}
```

## Stack Instantiation (`stack.ts`)

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ApplicationStack } from "./index";

const config = new pulumi.Config();
const projectName = pulumi.getProject();
const environment = pulumi.getStack();

const appStack = new ApplicationStack("application", {
  projectName,
  environment,
  bucketVersioning: config.getBoolean("bucketVersioning") ?? true,
  bucketEncryption: config.get("bucketEncryption") ?? "AES256",
  dbInstanceClass: config.get("dbInstanceClass") ?? "db.t3.micro",
  dbAllocatedStorage: config.getNumber("dbAllocatedStorage") ?? 20,
  dbMultiAz: config.getBoolean("dbMultiAz") ?? false,
  dbDeletionProtection: config.getBoolean("dbDeletionProtection") ?? true,
  dbBackupRetentionPeriods: config.getNumber("dbBackupRetentionPeriods") ?? 7,
  kmsKeyId: config.get("kmsKeyId"),
});

export const bucketArn = appStack.bucketArn;
export const bucketName = appStack.bucketName;
export const rdsEndpoint = appStack.rdsEndpoint;
export const iamRoleArn = appStack.iamRoleArn;
```

## Configuration Files

### `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  bucketVersioning: true
  bucketEncryption: AES256
  dbInstanceClass: db.t3.micro
  dbAllocatedStorage: 20
  dbMultiAz: false
  dbDeletionProtection: true
  dbBackupRetentionPeriods: 7
  dbPassword:
    secure: AAAFACfXgEv7CwB...  # Run: pulumi config set --secret dbPassword <password>
```

### `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  bucketVersioning: true
  bucketEncryption: aws:kms
  kmsKeyId: arn:aws:kms:us-east-1:123456789012:key/12345678-1234-1234-1234-123456789012
  dbInstanceClass: db.t3.medium
  dbAllocatedStorage: 100
  dbMultiAz: true
  dbDeletionProtection: true
  dbBackupRetentionPeriods: 30
  dbPassword:
    secure: AAAFACfXgEv7CwB...  # Run: pulumi config set --secret dbPassword <password>
```

## Setup & Deployment

```bash
# Install dependencies
npm install @pulumi/pulumi @pulumi/aws

# Create stacks
pulumi stack init dev
pulumi stack init prod

# Set secrets (interactive, not committed)
pulumi config set --secret dbPassword --stack dev
pulumi config set --secret dbPassword --stack prod

# Deploy
pulumi up --stack dev   # 2-min deployment, t3.micro RDS, 20GB storage, dev encryption
pulumi up --stack prod  # Multi-AZ, t3.medium, 100GB storage, KMS encryption, 30-day backup
```

## Key Features

| Criterion | Implementation |
|-----------|---|
| **Bucket encryption** | AES256 (dev) / KMS (prod) via config |
| **Versioning** | Enabled for both environments |
| **Public access** | Blocked via `BucketPublicAccessBlock` |
| **RDS deletion protection** | Enabled; no immediate teardown |
| **Backup retention** | 7 days (dev), 30 days (prod) |
| **Multi-AZ** | Dev: single, Prod: multi-AZ |
| **IAM least privilege** | No wildcard actions; scoped S3 paths, RDS ARN-specific |
| **Secrets** | Via Pulumi stack secrets (encrypted at rest) |
| **Environment isolation** | Independent stacks; `dev.yaml` ≠ `prod.yaml` |

Deploy with `pulumi up --stack dev` or `pulumi up --stack prod` for independent, reproducible infrastructure.
